<script>
document.addEventListener('DOMContentLoaded',function(){const modal=document.querySelector('#account-modal'),form=document.querySelector('#account-form');function closeModal(){modal.classList.remove('open')}document.querySelectorAll('.account-edit').forEach(function(button){button.addEventListener('click',function(){const account=JSON.parse(button.dataset.account);form.action='{{ url('/admin/accounts') }}/'+account.id;form.elements.full_name.value=account.full_name||'';form.elements.email.value=account.email||'';form.elements.phone.value=account.phone||'';form.elements.role.value=account.role||'student';form.elements.status.value=account.status||'active';form.elements.country.value=account.country||'';form.elements.city.value=account.city||'';form.elements.password.value='';modal.classList.add('open');form.elements.full_name.focus()})});modal.querySelector('.close-modal').addEventListener('click',closeModal);modal.querySelector('.cancel-modal').addEventListener('click',closeModal);modal.addEventListener('click',function(event){if(event.target===modal)closeModal()});document.addEventListener('keydown',function(event){if(event.key==='Escape')closeModal()})});
</script>
